(function () {
  const canvas = document.getElementById('hero-particles');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  let W = 0, H = 0, DPR = 1, particles = [];
  const mouse = { x: -9999, y: -9999, active: false };
    let lastScrollY = window.scrollY;

  const DOT_WHITE = 'rgba(255, 255, 255, 0.75)';
  const DOT_GOLD  = 'rgba(212, 175, 85, 0.95)';
  const LINE_RGB  = '212, 175, 85';
  const LINK_DIST = 180;
  const MOUSE_RADIUS = 200;

    let lastW = 0, lastH = 0;
  function resize() {
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    const vv = window.visualViewport;
    const newW = vv ? Math.round(vv.width) : window.innerWidth;
    const newH = vv ? Math.round(vv.height) : window.innerHeight;

    // Ignore small height changes (mobile address bar toggling ~60-120px)
    const widthChanged = Math.abs(newW - lastW) > 30;
    const heightChanged = Math.abs(newH - lastH) > 150;
    if (!widthChanged && !heightChanged && particles.length > 0) {
      // Still resize canvas to match current visual viewport, no rebuild
      W = newW; H = newH;
      canvas.width = W * DPR;
      canvas.height = H * DPR;
      canvas.style.width = W + 'px';
      canvas.style.height = H + 'px';
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      return;
    }

    W = newW; H = newH;
    lastW = W; lastH = H;
    canvas.width = W * DPR;
    canvas.height = H * DPR;
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    // Fewer particles on small screens
    const isMobile = W < 700;
    const divisor = isMobile ? 9000 : 5000;
    const cap = isMobile ? 120 : 280;
    const target = Math.min(Math.max(Math.floor((W * H) / divisor), 30), cap);
    particles = [];
    for (let i = 0; i < target; i++) {
      particles.push({
        x: Math.random() * W,
        y: Math.random() * H,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3,
        r: 0.9 + Math.random() * 2.0,
        gold: Math.random() < 0.45
      });
    }
  }

   function drawFrame() {
    // Scroll the particle field with the page
    const currentScrollY = window.scrollY;
    const scrollDelta = currentScrollY - lastScrollY;
    lastScrollY = currentScrollY;

    if (scrollDelta !== 0) {
      for (const p of particles) {
        p.y -= scrollDelta;
        if (p.y < -15) p.y = H + 15;
        else if (p.y > H + 15) p.y = -15;
      }
    }

    ctx.clearRect(0, 0, W, H);


    for (const p of particles) {
      if (mouse.active) {
        const dx = p.x - mouse.x, dy = p.y - mouse.y;
        const d2 = dx * dx + dy * dy;
        if (d2 < MOUSE_RADIUS * MOUSE_RADIUS && d2 > 1) {
          const d = Math.sqrt(d2);
          const f = (1 - d / MOUSE_RADIUS) * 0.18;
          p.vx += (dx / d) * f;
          p.vy += (dy / d) * f;
        }
      }
      p.vx *= 0.985; p.vy *= 0.985;
      p.vx += (Math.random() - 0.5) * 0.012;
      p.vy += (Math.random() - 0.5) * 0.012;
      const sp = Math.hypot(p.vx, p.vy);
      if (sp > 1.2) { p.vx = (p.vx / sp) * 1.2; p.vy = (p.vy / sp) * 1.2; }
      p.x += p.vx; p.y += p.vy;
      if (p.x < -15) p.x = W + 15;
      if (p.x > W + 15) p.x = -15;
      if (p.y < -15) p.y = H + 15;
      if (p.y > H + 15) p.y = -15;
    }

    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        const a = particles[i], b = particles[j];
        const dx = a.x - b.x, dy = a.y - b.y;
        const d2 = dx * dx + dy * dy;
        if (d2 < LINK_DIST * LINK_DIST) {
          const alpha = (1 - Math.sqrt(d2) / LINK_DIST) * 0.42;
          ctx.strokeStyle = 'rgba(' + LINE_RGB + ',' + alpha + ')';
          ctx.lineWidth = 0.7;
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.stroke();
        }
      }
    }

    for (const p of particles) {
      ctx.fillStyle = p.gold ? DOT_GOLD : DOT_WHITE;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  let rafId = null, running = false;
  function loop() { drawFrame(); rafId = requestAnimationFrame(loop); }
  function start() { if (running || reduced) return; running = true; rafId = requestAnimationFrame(loop); }
  function stop() { running = false; if (rafId) cancelAnimationFrame(rafId); rafId = null; }

    window.addEventListener('pointermove', (e) => {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
    mouse.active = true;
  });
  window.addEventListener('pointerup', () => { mouse.active = false; });
  window.addEventListener('touchend', () => { mouse.active = false; });
  document.addEventListener('mouseleave', () => { mouse.active = false; });

  window.addEventListener('resize', () => { resize(); drawFrame(); });
  resize();
  drawFrame();
  if (!reduced) start();
})();
</script>
